"""Analyze cached cross-border category pages. Standard library only; no network."""
import json
import math
import re
import sys
import unicodedata
from collections import Counter
from difflib import SequenceMatcher
from pathlib import Path


def number(value):
    if value is None or isinstance(value, bool):
        return None
    try:
        result = float(str(value).strip().removesuffix("%"))
        return result if math.isfinite(result) else None
    except (TypeError, ValueError):
        return None


def normalize_title(value):
    text = unicodedata.normalize("NFKC", str(value or "")).casefold()
    return "".join(c for c in text if c.isalnum())


def category_path(row):
    return tuple(x.strip() for x in re.split(r"[>＞]", str(row.get("levelName") or "")) if x.strip())


def similar(a, b):
    pa, pb = number(a.get("price")), number(b.get("price"))
    if pa is None or pb is None or min(pa, pb) <= 0 or max(pa, pb) > min(pa, pb) * 1.1 + 1e-9:
        return False
    aid, bid = a.get("leafCategoryId"), b.get("leafCategoryId")
    if aid is not None and bid is not None:
        if str(aid) != str(bid):
            return False
    elif not category_path(a) or category_path(a) != category_path(b):
        return False
    ta, tb = normalize_title(a.get("title")), normalize_title(b.get("title"))
    if not ta or not tb:
        return False
    for x, y in ((ta, tb), (tb, ta)):
        matcher = SequenceMatcher(None, x, y, autojunk=False)
        if matcher.quick_ratio() <= 0.8 or matcher.ratio() <= 0.8:
            return False
    return True


def cluster(rows):
    groups = []
    for row in sorted(rows, key=lambda r: str(r["offerId"])):
        for group in groups:
            if all(similar(row, member) for member in group):
                group.append(row)
                break
        else:
            groups.append([row])
    return groups


def supplier_key(row):
    for field in ("shopId", "shopUrl", "company"):
        if row.get(field):
            return field, str(row[field]).strip()
    return None


def source_stats(rows, groups):
    identities = {supplier_key(r) for r in rows if supplier_key(r)}
    ids = {str(r["offerId"]) for r in rows}
    sizes = [sum(str(r["offerId"]) in ids for r in g) for g in groups]
    return {"identifiableSuppliers": len(identities),
            "missingSupplierIdentity": sum(supplier_key(r) is None for r in rows),
            "suspectedDuplicateClusters": sum(n > 1 for n in sizes),
            "sourceGroups": sum(n > 0 for n in sizes)}


def analyze(data):
    pages = data.get("pages", [])
    if not pages:
        raise ValueError("No baseline pages supplied")
    root_name = data.get("categoryName")
    if not isinstance(root_name, str) or not root_name.strip():
        raise ValueError("categoryName is required for levelName cleaning")
    excluded = set(data.get("excludedPathNames", []))
    counts, records, seen_ids, seen_pages = set(), {}, set(), set()
    for page in pages:
        n, index, size = page.get("totalCount"), page.get("pageIndex"), page.get("pageSize")
        if not all(isinstance(v, int) and not isinstance(v, bool) for v in (n, index, size)):
            raise ValueError("Integer totalCount/pageIndex/pageSize required")
        if n < 0 or index < 1 or size != 100:
            raise ValueError("Expected nonnegative total, pageIndex>=1, pageSize=100")
        if index in seen_pages:
            raise ValueError("Duplicate page; reuse cached pages instead of merging twice")
        seen_pages.add(index)
        counts.add(n)
        rows = page.get("list")
        if not isinstance(rows, list) or len(rows) > size:
            raise ValueError("Invalid page list")
        for j, source in enumerate(rows):
            row = dict(source)
            oid = row.get("offerId")
            if oid is None or not str(oid).strip():
                raise ValueError("Missing stable offerId")
            if str(oid) in seen_ids:
                raise ValueError("Repeated offerId across baseline pages; snapshot may have drifted")
            seen_ids.add(str(oid))
            pos = (index - 1) * size + j + 1
            amount = number(row.get("salesVolume"))
            if pos > n or amount is None or amount < 0:
                raise ValueError("Invalid position or salesVolume")
            row["salesVolume"] = amount
            row["salesSortPosition"] = pos
            records[pos] = row
    if len(counts) != 1:
        raise ValueError("totalCount changed across pages; do not combine snapshots")
    n = counts.pop()
    positions = sorted(records)
    if any(records[a]["salesVolume"] < records[b]["salesVolume"] for a, b in zip(positions, positions[1:])):
        raise ValueError("Sales ordering invalid; local partial sorting cannot establish category percentiles")
    prefix = 0
    while prefix + 1 in records:
        prefix += 1
    previous_amount, rank = None, None
    for pos in positions:
        row = records[pos]
        if pos <= prefix:
            if row["salesVolume"] != previous_amount:
                rank = pos
            row["categorySalesRank"] = rank
            previous_amount = row["salesVolume"]
        else:
            row["categorySalesRank"] = None
    k10 = max(1, math.ceil(n * 0.1)) if n else 0
    k30 = max(1, math.ceil(n * 0.3)) if n else 0
    threshold = records[k10]["salesVolume"] if k10 in records else None
    tie_complete = n == 0 or (threshold is not None and prefix >= k10 and
                              (prefix == n or records[prefix]["salesVolume"] < threshold))
    base = {"totalCount": n, "countMayBeCapped": n >= 10000,
            "rawFetched": len(positions), "uniqueFetched": len(seen_ids),
            "coverage": len(seen_ids) / n if n else None,
            "k10": k10, "k30": k30, "threshold": threshold,
            "contiguousPrefix": prefix,
            "top10PositionCoverage": min(prefix, k10) / k10 if k10 else None,
            "boundaryTieCoverageComplete": tie_complete,
            "selectionVerified": tie_complete,
            "rankingScope": "cross-border category, interface-reported population",
            "exclusions": {}, "qualifiedCount": 0, "displayedCount": 0,
            "allQualifiedSourceStats": {}, "displayedSourceStats": {}, "rows": []}
    if threshold is None:
        base["status"] = "empty_category" if n == 0 else "missing_boundary"
        return base
    reasons, candidates = Counter(), []
    allowed_ids = data.get("candidateIds")
    if allowed_ids is not None:
        allowed_ids = set(map(str, allowed_ids))
    for pos in positions:
        row = records[pos]
        path = category_path(row)
        growth = number(row.get("bookedCount7dGrowthRate"))
        if not path:
            reason = "missing_category_path"
        elif path[0] != root_name.strip() or excluded.intersection(path):
            reason = "wrong_category_or_accessory"
        elif row["salesVolume"] < threshold:
            reason = "below_top10_threshold"
        elif growth is None:
            reason = "missing_growth"
        elif growth < 10:
            reason = "growth_below_10_percent"
        elif allowed_ids is not None and str(row["offerId"]) not in allowed_ids:
            reason = "additional_user_conditions"
        else:
            row["growthPercent"] = growth
            candidates.append(row)
            continue
        reasons[reason] += 1
    groups = cluster(candidates)
    for i, group in enumerate(groups, 1):
        for row in group:
            row["sourceGroup"] = i
            row["suspectedSameSourceWith"] = [str(r["offerId"]) for r in group if r is not row]
    candidates.sort(key=lambda r: (-r["growthPercent"], -r["salesVolume"], str(r["offerId"])))
    shown = candidates[:20]
    base.update(status="complete_top10_scan" if tie_complete else "partial_candidate_scan",
                exclusions=dict(reasons), qualifiedCount=len(candidates), displayedCount=len(shown),
                allQualifiedSourceStats=source_stats(candidates, groups),
                displayedSourceStats=source_stats(shown, groups), rows=shown)
    return base


if __name__ == "__main__":
    if len(sys.argv) != 3:
        raise SystemExit("Usage: python analyze.py input.json output.json")
    payload = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
    result = analyze(payload)
    Path(sys.argv[2]).write_text(json.dumps(result, ensure_ascii=False, indent=2, allow_nan=False) + "\n", encoding="utf-8")
